"""A Class for performing sequenced interactions to log out of a MOSAIQ application"""

from ..interactions import MosaiqLogout

class Logout():
    def __init__(self) -> None:
        pass

    def logoutUser(self) -> None:
        MosaiqLogout.click_logout_button()
        if MosaiqLogout.confirm_successful_logout(30000):
            print("Logged out")

    def exitApplication(self) -> None:
        MosaiqLogout.click_exit_button()
        if MosaiqLogout.confirm_successful_exit(30000):
            print("Exited application")
